function tourSeconds(points: number[][]): number {
  let seconds = 0;
  let [x, y] = points[0];
  for (let i = 1; i < points.length; i++) {
    const [tx, ty] = points[i];
    while (x !== tx || y !== ty) {
      x += Math.sign(tx - x);
      y += Math.sign(ty - y);
      seconds++;
    }
  }
  return seconds;
}

