class Solution:
    def tourSeconds(self, points: List[List[int]]) -> int:
        def sign(v):
            return (v > 0) - (v < 0)

        seconds = 0
        x, y = points[0]
        for tx, ty in points[1:]:
            while x != tx or y != ty:
                x += sign(tx - x)
                y += sign(ty - y)
                seconds += 1
        return seconds

